79:         /** Creates the purchase cart for a mode and a domain. */
80:         JSONObject createCart(String mode, String domain) throws Exception;
81: 
82:         /**
83:          * Richer all-domains call. The default keeps existing backends working by reusing
84:          * {@link #fetchAllDomains()}.
85:          */
86:         default JSONObject fetchAllDomainsPage() throws Exception {
87:             return fetchAllDomains();
88:         }
