90:         /**
91:          * Richer suggestions call returning the response envelope so that a mismatching response can
92:          * be detected. The default wraps {@link #searchForDomains(String)} into the same envelope.
93:          */
94:         default JSONObject searchDomainSuggestions(String query) throws Exception {
95:             JSONArray suggestions = searchForDomains(query);
96:             JSONObject envelope = Json.object();
97:             Json.put(envelope, "query", query);
98:             Json.put(envelope, "suggestions", suggestions == null ? Json.array() : suggestions);
99:             return envelope;
100:         }
101: 
102:         /**
103:          * Richer cart call carrying the product identifier, the privacy capability and the site a
104:          * domain should be attached to. The default keeps existing backends working by reusing
105:          * {@link #createCart(String, String)}.
106:          */
107:         default JSONObject createCartForProposal(JSONObject request) throws Exception {
108:             String mode = request == null ? "" : request.optString("mode", "");
109:             String domain = request == null ? "" : request.optString("domain", "");
110:             JSONObject response = createCart(mode, domain);
111:             return response == null ? null : response;
112:         }
