306:     /**
307:      * Runs a user intent through the flow. Every name is a screen action, not a test hook: the
308:      * transitions are the same ones the activities trigger.
309:      */
310:     public void invoke(String name, JSONObject event) throws Exception {
311:         JSONObject payload = event == null ? Json.object() : event;
312:         trace.add("DomainPageOwner." + name);
313:         switch (name) {
314:             case "openDomainManagement":
315:             case "openAllDomains":
316:             case "showAllDomains":
317:             case "openDomainManagementWithLoadedDomains":
318:                 openAllDomains();
319:                 break;
320:             case "openDomainManagementThenTapAddDomain":
321:                 openAllDomains();
322:                 tapAddDomain();
323:                 break;
324:             case "openDomainManagementThenTapFindDomain":
325:                 openAllDomains();
326:                 tapFindDomain();
327:                 break;
328:             case "tapAddDomain":
329:             case "tapFindDomain":
330:             case "tapAddDomainAction":
331:             case "tapFindADomain":
332:             case "tapEmptyStateAction":
333:             case "tapEmptyStateAddDomain":
334:                 tapAddDomain();
335:                 break;
336:             case "refreshDomains":
337:             case "reloadDomains":
338:                 refreshDomains();
339:                 break;
340:             case "tapRetry":
341:                 retryCurrentScreen();
342:                 break;
343:             case "retryList":
344:             case "retryDomainList":
345:             case "retryLoadDomains":
346:                 retryList();
347:                 break;
348:             case "enterLocalFilter":
349:             case "setLocalFilter":
350:             case "enterFilter":
351:             case "typeFilter":
352:                 onLocalFilterChanged(payload.optString("query", payload.optString("filter", "")));
353:                 break;
354:             case "clearLocalFilter":
355:             case "clearFilter":
356:                 clearLocalFilter();
357:                 break;
358:             case "openSearch":
359:             case "openDomainSearch":
360:             case "startDomainSearch":
361:             case "showDomainSearch":
362:                 openSearch(payload);
363:                 break;
364:             case "enterRemoteQuery":
365:             case "enterSearchQuery":
366:             case "enterRemoteSearchQuery":
367:             case "typeSearchQuery":
368:             case "onSearchQueryChanged":
369:             case "searchForDomains":
370:                 enterRemoteQuery(payload);
371:                 break;
372:             case "advanceControlledClockAndCompleteRequests":
373:             case "advanceControlledClock":
374:             case "advanceClock":
375:             case "advanceTime":
376:             case "tickClock":
377:                 advanceClock(payload);
378:                 break;
379:             case "showProposals":
380:             case "showSearchResults":
