481:     /** Production entry point used by the all-domains screen. */
482:     public void refreshDomains() {
483:         final Backend currentBackend = backend;
484:         if (currentBackend == null) {
485:             applyListError("no domain backend is available");
486:             return;
487:         }
488:         final int requestId = ++listRequestCount;
489:         setListState(LIST_LOADING);
490:         listError = "";
491:         trace.add("DomainPageOwner.loadDomains()");
492:         emit("fetchAllDomains", "requestIndex", requestId, "count", listRequestCount,
493:                 "retainedQuery", filterQuery);
494:         scheduler.executeOnWorker(new Runnable() {
495:             @Override public void run() {
496:                 JSONObject response;
497:                 try {
498:                     response = currentBackend.fetchAllDomainsPage();
499:                 } catch (Exception error) {
500:                     response = errorResponse(error);
501:                 }
502:                 final JSONObject payload = response;
503:                 scheduler.post(new Runnable() {
504:                     @Override public void run() {
505:                         applyListResponse(requestId, payload);
506:                     }
507:                 });
508:             }
509:         });
510:     }
