532:     /** Retry repeats whichever operation produced the visible error. */
533:     public void retryCurrentScreen() {
534:         if (listState == LIST_ERROR && !detailsScreenOpen && !checkoutScreenOpen) {
535:             retryList();
536:             return;
537:         }
538:         if (searchState == SEARCH_ERROR) {
539:             retrySearch();
540:             return;
541:         }
542:         if (cartState == CART_ERROR) {
543:             acknowledgeCartError();
544:             submitCart();
545:             return;
546:         }
547:         emit("retryIgnored", "listState", listState, "searchState", searchState, "cartState", cartState);
548:     }
