550:     private void applyListResponse(int requestId, JSONObject response) {
551:         if (requestId != listRequestCount) {
552:             // A newer all-domains request is in flight; the stale response is dropped.
553:             emit("staleListResponseIgnored", "requestIndex", requestId);
554:             return;
555:         }
556:         listRequestLog.add(describeListResponse(response));
557:         if (isErrorResponse(response)) {
558:             applyListError(Text.isBlank(errorMessage(response))
559:                     ? "the account domains could not be loaded" : errorMessage(response));
560:             return;
561:         }
562:         JSONArray domains = domainsOf(response);
563:         if (domains == null) {
564:             if (isExplicitlyEmpty(response)) {
565:                 replaceAccountDomains(Json.array());
566:                 setListState(LIST_EMPTY);
567:                 filterAccountDomains(filterQuery);
568:                 notifyObservers();
569:                 return;
570:             }
571:             applyListError("the account domains response could not be read");
572:             return;
573:         }
574:         replaceAccountDomains(domains);
575:         setListState(accountDomains.isEmpty() ? LIST_EMPTY : LIST_COMPLETE);
576:         filterAccountDomains(filterQuery);
577:         notifyObservers();
578:     }
