580:     private void applyListError(String message) {
581:         listError = Text.orEmpty(message);
582:         visibleDomains.clear();
583:         setListState(LIST_ERROR);
584:         emit("allDomainsLoadFailed", "message", listError, "retryable", true);
585:         notifyObservers();
586:     }
