588:     private void replaceAccountDomains(JSONArray domains) {
589:         accountDomains.clear();
590:         for (int index = 0; index < domains.length(); index++) {
591:             JSONObject entry = domains.optJSONObject(index);
592:             if (entry == null) {
593:                 String value = domains.optString(index, "");
594:                 if (Text.isBlank(value)) {
595:                     continue;
596:                 }
597:                 accountDomains.add(new DomainRow(value, "", "", "", ""));
598:                 continue;
599:             }
600:             accountDomains.add(DomainRow.fromJson(entry));
601:         }
602:     }
