615:         emit("filterLoadedDomains",
616:                 "query", filterQuery,
617:                 "normalizedQuery", Text.normalizeQuery(filterQuery),
618:                 "matchedDomains", visibleDomains.size(),
619:                 "accountDomains", accountDomains.size());
