623:     /** Restores the complete source list without refetching it. */
624:     public void clearLocalFilter() {
625:         trace.add("DomainPageOwner.clearLocalFilter()");
626:         JSONObject before = listSnapshot();
627:         String query = filterQuery;
628:         filterQuery = "";
629:         filterAccountDomains(filterQuery);
630:         beforeClear = Json.object();
631:         Json.put(beforeClear, "query", query);
632:         Json.put(beforeClear, "state", before);
633:         Json.put(beforeClear, "after", listSnapshot());
634:         emit("restoreCompleteDomainList",
635:                 "clearedQuery", query,
636:                 "restoredDomains", visibleDomains.size(),
637:                 "refetched", false);
638:         notifyObservers();
639:     }
