641:     private void filterAccountDomains(String query) {
642:         String normalized = Text.normalizeQuery(query);
643:         visibleDomains.clear();
644:         for (DomainRow row : accountDomains) {
645:             if (row.matches(normalized)) {
646:                 visibleDomains.add(row);
647:             }
648:         }
649:         if (!isListUsable()) {
650:             // Nothing has been loaded yet, so there is no list to filter.
651:             return;
652:         }
653:         setListState(Text.isBlank(normalized)
654:                 ? (accountDomains.isEmpty() ? LIST_EMPTY : LIST_COMPLETE)
655:                 : LIST_FILTERED);
656:     }
