658:     private JSONObject listSnapshot() {
659:         JSONObject snapshot = Json.object();
660:         Json.put(snapshot, "listState", listState);
661:         Json.put(snapshot, "query", filterQuery);
662:         Json.put(snapshot, "visibleDomains", domainNames(visibleDomains));
663:         Json.put(snapshot, "visibleDomainRows", domainRows(visibleDomains));
664:         Json.put(snapshot, "accountDomains", domainNames(accountDomains));
665:         return snapshot;
