711:         final String query = normalized;
712:         pendingQuery = query;
713:         pendingDueAt = scheduler.nowMillis() + SEARCH_DEBOUNCE_MS;
714:         pendingDispatch = scheduler.postDelayed(new Runnable() {
715:             @Override public void run() {
