727:     /** Blank input never reaches the backend and keeps the results of the last real query. */
728:     private void onBlankSearchQuery() {
729:         boolean cancelledPending = cancelPendingDispatch();
730:         boolean searching = searchState == SEARCH_LOADING || searchState == SEARCH_DEBOUNCING;
731:         if (searching && proposals.isEmpty()) {
732:             // Nothing is in flight any more, so no response may claim the visible state.
733:             queryGeneration++;
734:             searchError = "";
735:             setSearchState(SEARCH_IDLE);
736:         }
737:         emit("blankSearchQueryIgnored",
738:                 "keptQuery", searchQuery,
739:                 "keptProposals", proposals.size(),
740:                 "cancelledPendingDispatch", cancelledPending);
741:         notifyObservers();
