744:     private void enterRemoteQuery(JSONObject payload) {
745:         registerSimulatedCompletions(payload);
746:         Long at = timestampOf(payload);
747:         if (at != null) {
748:             useControlledClock(at);
749:             advanceControlledClockTo(at);
750:         }
751:         String raw = payload.optString("query", payload.optString("searchQuery", ""));
752:         if (!searchScreenOpen()) {
753:             openSearch(Json.object());
754:         }
755:         onSearchQueryChanged(raw);
