758:     /** Moves a controlled clock forward, running everything that becomes due on the way. */
759:     public void advanceControlledClockTo(long targetMillis) {
760:         DomainScheduler active = scheduler;
761:         if (active instanceof ControlledDomainScheduler) {
762:             ((ControlledDomainScheduler) active).advanceTo(targetMillis);
763:         }
764:     }
765: 
766:     private void advanceClock(JSONObject payload) {
767:         registerSimulatedCompletions(payload);
768:         JSONArray completions = payload.optJSONArray("completions");
769:         if (completions != null) {
770:             for (int index = 0; index < completions.length(); index++) {
771:                 JSONObject entry = completions.optJSONObject(index);
772:                 if (entry != null) {
773:                     JSONObject completion = entry.optJSONObject("completion");
774:                     registerSimulatedCompletion(entry.optString("query", ""),
775:                             completion == null ? entry : completion);
776:                 }
777:             }
778:         }
779:         Long to = timestampOf(payload);
780:         if (to == null) {
781:             settlePendingWork();
782:             notifyObservers();
783:             return;
784:         }
785:         useControlledClock(to);
786:         emit("clockAdvanced", "toMs", to);
787:         advanceControlledClockTo(to);
788:         notifyObservers();
789:     }
