791:     /**
792:      * Runs every piece of page work that is already scheduled: a pending debounce and the responses
793:      * that land after it. Used by the wait steps of a driver, and when a clock is advanced without
794:      * a target time.
795:      */
796:     private void settlePendingWork() {
797:         if (!(scheduler instanceof ControlledDomainScheduler)) {
798:             return;
799:         }
800:         ControlledDomainScheduler clock = (ControlledDomainScheduler) scheduler;
801:         for (int round = 0; round < 16 && clock.hasPendingTasks(); round++) {
802:             long due = clock.nextDueAt();
803:             if (due < 0L) {
804:                 return;
805:             }
806:             clock.advanceTo(due);
807:         }
808:     }
809: 
810:     private void waitFor(String expectation) {
811:         settlePendingWork();
812:         trace.add("DomainPageOwner.await(" + expectation + ")");
813:         notifyObservers();
814:     }
