816:     private void dispatchSearch(final String normalizedQuery) {
817:         pendingDispatch = null;
818:         if (!normalizedQuery.equals(searchQuery)) {
819:             emit("searchDispatchSkipped",
820:                     "query", normalizedQuery,
821:                     "latestQuery", searchQuery,
822:                     "reason", "superseded before dispatch");
823:             return;
824:         }
825:         final Backend currentBackend = backend;
826:         if (currentBackend == null) {
827:             applySearchError(normalizedQuery, "no domain backend is available");
828:             return;
829:         }
830:         final int generation = queryGeneration;
831:         searchRequestCount++;
832:         latestDispatchedQuery = normalizedQuery;
833:         dispatchedQueries.add(normalizedQuery);
834:         searchError = "";
835:         setSearchState(SEARCH_LOADING);
836:         emit("searchForDomains",
837:                 "query", normalizedQuery,
838:                 "normalizedQuery", normalizedQuery,
839:                 "requestIndex", searchRequestCount,
840:                 "generation", generation);
841:         trace.add("DomainPageOwner.searchForDomains(" + normalizedQuery + ")");
842:         notifyObservers();
843:         scheduler.executeOnWorker(new Runnable() {
844:             @Override public void run() {
845:                 JSONObject response;
846:                 try {
847:                     response = currentBackend.searchDomainSuggestions(normalizedQuery);
848:                 } catch (Exception error) {
849:                     response = errorResponse(error);
850:                 }
851:                 final JSONObject payload = response == null
852:                         ? errorResponse(new IllegalStateException("the suggestions response was empty"))
853:                         : response;
854:                 scheduler.post(new Runnable() {
855:                     @Override public void run() {
856:                         deliverSearchResponse(generation, normalizedQuery, payload);
857:                     }
858:                 });
859:             }
860:         });
861:     }
862: 
863:     private void deliverSearchResponse(int generation, String query, JSONObject response) {
864:         SimulatedCompletion completion = findSimulatedCompletion(query);
865:         long dueAt = completion == null ? -1L : completion.dueAt;
866:         if (dueAt > scheduler.nowMillis()) {
867:             final int requestGeneration = generation;
868:             final String requestQuery = query;
869:             final JSONObject requestResponse = response;
870:             scheduler.postDelayed(new Runnable() {
871:                 @Override public void run() {
872:                     applySearchResponse(requestGeneration, requestQuery, requestResponse);
873:                 }
874:             }, dueAt - scheduler.nowMillis());
875:             return;
876:         }
877:         applySearchResponse(generation, query, response);
878:     }
879: 
880:     private void applySearchResponse(int generation, String query, JSONObject response) {
881:         if (generation != queryGeneration || !query.equals(searchQuery)) {
882:             emit("staleSearchCompletionIgnored",
883:                     "query", query,
884:                     "latestQuery", searchQuery,
885:                     "generation", generation,
886:                     "latestGeneration", queryGeneration);
887:             return;
888:         }
889:         if (isErrorResponse(response)) {
890:             applySearchError(query, Text.isBlank(errorMessage(response))
891:                     ? "the domain suggestions could not be loaded" : errorMessage(response));
892:             return;
893:         }
894:         String remoteQuery = Text.normalizeQuery(Text.first(response, new String[] { "query", "search", "searchedQuery" }));
895:         if (!Text.isBlank(remoteQuery) && !remoteQuery.equals(query)) {
896:             applySearchError(query, "the domain suggestions answered the query \"" + remoteQuery + "\"");
897:             return;
898:         }
899:         JSONArray suggestions = suggestionsOf(response);
900:         List<DomainSuggestion> paid = DomainSuggestion.paidProposals(suggestions);
901:         SimulatedCompletion completion = findSimulatedCompletion(query);
902:         if (paid.isEmpty() && completion != null && !completion.domains.isEmpty()) {
903:             JSONArray simulated = Json.array();
904:             for (String domain : completion.domains) {
905:                 simulated.put(domain);
906:             }
907:             paid = DomainSuggestion.paidProposals(simulated);
908:         }
909:         proposals.clear();
910:         proposals.addAll(paid);
911:         searchError = "";
912:         setSearchState(SEARCH_POPULATED);
913:         emit("searchResults",
914:                 "query", query,
915:                 "proposals", proposals.size(),
916:                 "excludedFreeSuggestions", countFreeSuggestions(suggestions));
917:         notifyObservers();
918:     }
919: 
920:     private void applySearchError(String query, String message) {
921:         searchError = Text.orEmpty(message);
922:         proposals.clear();
923:         setSearchState(SEARCH_ERROR);
924:         emit("searchFailed", "query", query, "message", searchError, "retryable", true);
925:         notifyObservers();
926:     }
