1003:     private DomainSuggestion proposalFrom(JSONObject payload) {
1004:         JSONObject proposalJson = payload.optJSONObject("proposal");
1005:         if (proposalJson == null) {
1006:             proposalJson = payload.optJSONObject("selectedProposal");
1007:         }
1008:         if (proposalJson != null) {
1009:             return DomainSuggestion.fromJson(proposalJson, 0d);
1010:         }
1011:         String domain = payload.optString("domain", "");
1012:         if (!Text.isBlank(domain)) {
1013:             DomainSuggestion visible = DomainSuggestion.findByDomain(proposals, domain);
1014:             if (visible != null) {
1015:                 return visible;
1016:             }
1017:             if (selectedProposal != null && selectedProposal.domain.equalsIgnoreCase(domain.trim())) {
1018:                 return selectedProposal;
1019:             }
1020:             return DomainSuggestion.fromJson(domain, 0d);
1021:         }
1022:         return selectedProposal;
1023:     }
