1066:     /** Chooses a purchase mode and submits the cart for it. */
1067:     public void selectPurchaseMode(String mode, JSONObject payload) {
1068:         if (selectedProposal == null) {
1069:             emit("purchaseModeIgnored", "reason", "no proposal was selected");
1070:             return;
1071:         }
1072:         String site = MODE_EXISTING_SITE.equals(mode)
1073:                 ? firstNonBlank(siteFrom(payload), existingSite) : "";
1074:         boolean sameAttempt = mode.equals(purchaseMode)
1075:                 && (!MODE_EXISTING_SITE.equals(mode) || site.equalsIgnoreCase(existingSite));
1076:         if (sameAttempt) {
1077:             // The same purchase is already submitted; a duplicate cart is never created.
1078:             emit("duplicateCartSubmissionIgnored",
1079:                     "mode", purchaseMode,
1080:                     "domain", selectedProposal.domain,
1081:                     "cartState", cartState);
1082:             return;
1083:         }
1084:         purchaseMode = mode;
1085:         existingSite = site;
1086:         resetCart();
1087:         purchaseScreenOpen = true;
1088:         screen = SCREEN_DOMAIN_PURCHASE;
1089:         if (MODE_EXISTING_SITE.equals(mode) && Text.isBlank(existingSite)) {
1090:             // An existing-site cart without a target site cannot be submitted yet.
1091:             cartProgress = "waitingForSite:" + mode;
1092:             cartProgressHistory.add(cartProgress);
1093:             emit("existingSiteRequired", "domain", selectedProposal.domain, "mode", mode);
1094:             notifyObservers();
1095:             return;
1096:         }
1097:         trace.add("DomainPageOwner.selectPurchaseMode(" + mode + ")");
1098:         submitCart();
1099:     }
