1113:     /** Submits the cart for the selected mode; at most one request per explicit attempt. */
1114:     public void submitCart() {
1115:         if (selectedProposal == null) {
1116:             emit("cartSubmissionIgnored", "reason", "no proposal was selected");
1117:             return;
1118:         }
1119:         if (Text.isBlank(purchaseMode)) {
1120:             emit("cartSubmissionIgnored", "reason", "no purchase mode was chosen",
1121:                     "domain", selectedProposal.domain);
1122:             return;
1123:         }
1124:         if (checkoutCompletionCount > 0) {
1125:             emit("cartSubmissionIgnored", "reason", "the checkout already completed",
1126:                     "domain", selectedProposal.domain);
1127:             return;
1128:         }
1129:         if (cartState == CART_SUBMITTING) {
1130:             emit("duplicateCartSubmissionIgnored", "mode", purchaseMode, "domain", selectedProposal.domain);
1131:             return;
1132:         }
1133:         if (cartState == CART_ERROR) {
1134:             emit("cartSubmissionIgnored", "reason", "the cart error has to be acknowledged first",
1135:                     "mode", purchaseMode, "domain", selectedProposal.domain);
1136:             return;
1137:         }
1138:         if (cartState == CART_COMPLETED) {
1139:             emit("duplicateCartSubmissionIgnored", "mode", purchaseMode, "domain", selectedProposal.domain);
1140:             return;
1141:         }
1142:         final Backend currentBackend = backend;
1143:         if (currentBackend == null) {
1144:             applyCartError(purchaseMode, selectedProposal.domain, "no domain backend is available");
1145:             return;
1146:         }
1147:         final int requestId = ++cartRequestCount;
1148:         final String mode = purchaseMode;
1149:         final String domain = selectedProposal.domain;
1150:         final JSONObject request = cartRequest(mode, domain);
1151:         cartState = CART_SUBMITTING;
1152:         cartProgress = "submitting:" + mode;
1153:         cartProgressHistory.add(cartProgress);
1154:         cartError = "";
1155:         emit("cartSubmitted", "mode", mode, "domain", domain, "requestIndex", requestId,
1156:                 "productId", selectedProposal.productId, "supportsPrivacy", selectedProposal.supportsPrivacy,
1157:                 "progress", cartProgress);
1158:         trace.add("DomainPageOwner.createCart(" + mode + ")");
1159:         notifyObservers();
1160:         scheduler.executeOnWorker(new Runnable() {
1161:             @Override public void run() {
1162:                 JSONObject response;
1163:                 try {
1164:                     response = currentBackend.createCartForProposal(request);
1165:                 } catch (Exception error) {
1166:                     response = errorResponse(error);
1167:                 }
1168:                 final JSONObject payload = response == null
1169:                         ? errorResponse(new IllegalStateException("the cart could not be created")) : response;
1170:                 scheduler.post(new Runnable() {
1171:                     @Override public void run() {
1172:                         applyCartResponse(requestId, mode, domain, payload);
1173:                     }
1174:                 });
1175:             }
1176:         });
1177:     }
