1223:     private void applyCartResponse(int requestId, String mode, String domain, JSONObject response) {
1224:         if (requestId != cartRequestCount || !mode.equals(purchaseMode)) {
1225:             // A newer attempt, or a different purchase mode, owns the purchase screen now.
1226:             emit("staleCartResponseIgnored", "requestIndex", requestId, "mode", mode,
1227:                     "currentMode", purchaseMode);
1228:             return;
1229:         }
1230:         if (isErrorResponse(response)) {
1231:             applyCartError(mode, domain, Text.isBlank(errorMessage(response))
1232:                     ? "the domain could not be added to the cart" : errorMessage(response));
1233:             return;
1234:         }
1235:         cartToken = Text.first(response, new String[] { "checkoutToken", "checkout_token", "token", "cartToken" });
1236:         cartUrl = Text.first(response, new String[] { "checkoutUrl", "checkout_url", "url" });
1237:         cartEmail = Text.first(response, new String[] { "email", "userEmail", "user_email", "ownerEmail" });
1238:         planRequired = requiresPlan(response, mode);
1239:         cartState = CART_COMPLETED;
1240:         cartProgress = "completed:" + mode;
1241:         cartProgressHistory.add(cartProgress);
1242:         checkoutScreenOpen = !planRequired;
1243:         destination = planRequired ? DESTINATION_PLANS : DESTINATION_CHECKOUT;
1244:         emit("cartCompleted", "mode", mode, "domain", domain, "checkoutToken", cartToken,
1245:                 "planRequired", planRequired);
1246:         emit("navigate", "destination", destination, "mode", mode, "domain", domain,
1247:                 "checkoutToken", cartToken, "checkoutUrl", cartUrl, "site", existingSite);
1248:         notifyObservers();
