7: /**
8:  * Containment policy for the in-app domain details web view.
9:  *
10:  * <p>The details screen may keep only {@code wordpress.com/domains/manage/all/<domain>/edit/...}
11:  * for the managed domain. Any other host, another domain, or another path inside the account area
12:  * is rejected and handed to the external navigation path so that the authenticated web view never
13:  * ends up on an unsupported page.</p>
14:  */
15: public final class DomainUrlPolicy {
16: 
17:     public static final String CONTAINED_HOST = "wordpress.com";
18:     public static final String ALL_DOMAINS_PATH_PREFIX = "/domains/manage/all/";
19:     public static final String DETAILS_SUB_PATH = "edit";
20:     public static final String DEFAULT_DETAILS_SUB_PATH = "contact";
21: 
22:     /** The details destination used by the "All Domains" rows. */
23:     public static String containedDetailsUrl(String domain) {
24:         return "https://" + CONTAINED_HOST + ALL_DOMAINS_PATH_PREFIX + pathSegment(domain)
25:                 + "/" + DETAILS_SUB_PATH + "/" + DEFAULT_DETAILS_SUB_PATH;
26:     }
27: 
28:     /** True when the web view is allowed to keep the destination for the managed domain. */
29:     public boolean isContained(String url, String managedDomain) {
30:         if (Text.isBlank(url) || Text.isBlank(managedDomain)) {
31:             return false;
32:         }
33:         URI uri = parse(url);
34:         if (uri == null) {
35:             return false;
36:         }
37:         String scheme = Text.orEmpty(uri.getScheme()).toLowerCase(Locale.ROOT);
38:         if (!scheme.equals("https")) {
39:             return false;
40:         }
41:         String host = Text.orEmpty(uri.getHost()).toLowerCase(Locale.ROOT);
42:         if (!host.equals(CONTAINED_HOST)) {
43:             return false;
44:         }
45:         String path = Text.orEmpty(uri.getPath());
46:         if (!path.startsWith(ALL_DOMAINS_PATH_PREFIX)) {
47:             return false;
48:         }
49:         String[] segments = path.substring(ALL_DOMAINS_PATH_PREFIX.length()).split("/");
50:         // /domains/manage/all/<domain>/edit[/<page>]
51:         if (segments.length < 2 || segments.length > 3) {
52:             return false;
53:         }
54:         for (String segment : segments) {
55:             if (segment.isEmpty() || ".".equals(segment) || "..".equals(segment)) {
56:                 return false;
57:             }
58:         }
59:         if (!segments[0].equalsIgnoreCase(managedDomain)) {
60:             return false;
61:         }
62:         return segments[1].equals(DETAILS_SUB_PATH);
63:     }
64: 
65:     /** Reads the managed domain out of a details URL, or an empty string when it is not one. */
66:     public String managedDomainOf(String url) {
67:         URI uri = parse(url);
68:         if (uri == null) {
69:             return "";
70:         }
71:         String path = Text.orEmpty(uri.getPath());
72:         if (!path.startsWith(ALL_DOMAINS_PATH_PREFIX)) {
73:             return "";
74:         }
75:         String[] segments = path.substring(ALL_DOMAINS_PATH_PREFIX.length()).split("/");
76:         return segments.length > 0 ? segments[0] : "";
77:     }
